const mensajes = $node["Get Data"].json["Mensaje"];
const msg = Array.isArray(mensajes) ? mensajes.join(', ') : String(mensajes||'');
return [{ json: {
  mensaje_completo: msg,
  phone: $('WhatsApp Trigger').item.json.messages[0].from,
  msg_type: $('Filtrador').item.json.type || 'text'
}}];

const intent = ($json.text || 'otro').trim().toLowerCase();
const validIntents = ['agendar','consultar','precios','urgencia','reprogramar','cancelar','confirmar','seguimiento','saludo','otro'];
const cleanIntent = validIntents.includes(intent) ? intent : 'otro';

return [{ json: {
  mensaje_completo: $('Set Mensaje Completo').item.json.mensaje_completo,
  phone: $('Set Mensaje Completo').item.json.phone,
  msg_type: $('Set Mensaje Completo').item.json.msg_type,
  idioma: $('Traductor').item.json.text || 'Portugués',
  intent: cleanIntent,
  is_urgent: cleanIntent === 'urgencia'
}}];

const ctx = $('Set Contexto').item.json;
const cfg = $('Config Cliente').item.json;
return [{ json: {
  action: ctx.intent,
  phone: ctx.phone,
  client_id: cfg.client_id,
  business_phone_id: cfg.business_phone_id || '',
  idioma: ctx.idioma
}}];

const ctx = .item.json;
const cfg = .item.json;
const planCrm = .item.json[0]?.crm || false;
return [{ json: {
  action: 'upsert',
  phone: ctx.phone,
  client_id: cfg.client_id,
  plan_crm: planCrm,
  name: null
}}];

const patient = $('Merge Pre-Agente').item.json;
const ctx = $('Set Contexto').item.json;
const agente = $('Agente de IA').item.json;
const cfg = $('Config Cliente').item.json;
return [{ json: {
  action: 'post_conversation',
  patient_id: patient.patient_id,
  patient_status: patient.patient_status || 'desconocido',
  patient_score: patient.patient_score || 0,
  is_new: patient.is_new || false,
  intent: ctx.intent,
  mensaje_usuario: ctx.mensaje_completo,
  respuesta_agente: agente.output || '',
  client_id: cfg.client_id
}}];

